constraints:
1 ≤ N, M ≤ 10^{6}
1 ≤ A1[i], A2[i] ≤ 10^{6}

expected time complexity: O(N * Log(N)).
expected auxiliary space: O(N).

standard_solution_code:
class Solution:

	def relativeSort(self, A1, N, A2, M):
		d = {}
		for i in A1:
			d[i] = d.get(i, 0) + 1
		ans = []
		flg = 0
		for i in A2:
			if i in d:
				ans.extend([i] * d[i])
				d[i] = 0
				flg = 1
		tmp = len(ans)
		for i in d:
			if d[i] != 0:
				ans.extend([i] * d[i])
		if flg == 0:
			return sorted(A1)
		else:
			ans[tmp:] = sorted(ans[tmp:])
			return ans
